@startuml

class Department {}

class Room {}

class Bed {}

class Category {
  +price: float
}

enum CategoryType {
  RH
  RNH
  SF
}

class Inhabitant {
  +name: string
}

class Stay {
  +startDate: date
  +endDate: date
  +isSuspended: boolean
}

class Registration {
  +registrationDate: date
  +identificationData: string
}

class Assessment {
  +needsEatingHelp: boolean
  +needsDressingHelp: boolean
  +needsPersonalCareHelp: boolean
  +resultingStayType: CategoryType
}

class WaitingListEntry {
  +position: int
}

class Proposal {
  +proposalDate: date
  +isAccepted: boolean
  +isRefused: boolean
  +isInvalidated: boolean
}

class Invoice {
  +date: date
  +outstandingAmount: float
  +isPaid: boolean
}

class CreditNote {
  +amount: float
}

Department "1" *-- "*" Room
Room "1" *-- "*" Bed
Bed "*" -- "1" Category
Inhabitant "1" -- "*" Stay
Stay "*" -- "1" Category
Inhabitant "1" -- "0..1" Registration
Registration "1" -- "0..1" Assessment
Assessment "1" -- "*" WaitingListEntry
WaitingListEntry "*" -- "1" Category
WaitingListEntry "0..1" -- "1" Proposal
Proposal "0..1" -- "1" Inhabitant
Stay "1" -- "*" Invoice
Inhabitant "1" -- "*" Invoice
Invoice "0..1" -- "0..1" CreditNote

@enduml

